import { useEffect, useMemo } from 'react';
import * as THREE from 'three';
import { fundusVessels, vec } from '../eye/anchors';

/**
 * The retinal vessels seen in the fundus: arteries (brighter red, narrower) and veins (darker,
 * wider) leaving the optic disc. Drawn on the inner surface of the HuBMAP retina; the branching
 * pattern is illustrative (generated by tools/extract-eye.mjs), the disc and fovea are real.
 */
export function FundusVessels() {
  const meshes = useMemo(() => fundusVessels.map((v) => {
    const curve = new THREE.CatmullRomCurve3(v.points.map((p) => new THREE.Vector3(...vec(p))), false, 'centripetal');
    const g = new THREE.TubeGeometry(curve, Math.max(8, v.points.length * 3), v.widthMm / 2000, 6, false);
    return { g, kind: v.kind };
  }), []);
  const artery = useMemo(() => new THREE.MeshStandardMaterial({ color: '#c0302a', roughness: 0.35, emissive: '#3a0806', emissiveIntensity: 0.3 }), []);
  const vein = useMemo(() => new THREE.MeshStandardMaterial({ color: '#7a1c24', roughness: 0.35, emissive: '#200406', emissiveIntensity: 0.3 }), []);
  useEffect(() => () => { meshes.forEach((m) => m.g.dispose()); artery.dispose(); vein.dispose(); }, [meshes, artery, vein]);
  return (
    <group>
      {meshes.map((m, i) => <mesh key={i} geometry={m.g} material={m.kind === 'artery' ? artery : vein} renderOrder={3} />)}
    </group>
  );
}
